import React, { useState } from "react";
import { BrowserRouter as Router, Routes, Route, Navigate } from "react-router-dom";

import "./App.scss";
import LoginRegisterForm from "./components/LoginRegisterContainer/LoginRegisterContainer";
import AdminCustomerContainer from "./components/AdminCustomerContainer/AdminCustomerContainer";
import SellerContainer from "./components/SellerContainer/SellerContainer";
import CustomerContainer from "./components/CustomerContainer/CustomerContainer";
import ProfileUpdate from "./components/ProfileUpdate/ProfileUpdate";

function App() {
  let [isUserAuthenticated, setUserAuthorization] = useState(
    sessionStorage.getItem("isUserAuthenticated") === "true" || false
  );
  let [userRole, setUserRole] = useState(
    sessionStorage.getItem("userRole") || "customer" // Détermine le rôle par défaut (customer, admin ou seller)
  );
  let [customerId, setCustomerId] = useState(
    sessionStorage.getItem("customerId") || undefined
  );

  const setUserAuthenticatedStatus = (role, customerId) => {
    setUserAuthorization(true);
    setUserRole(role);
    setCustomerId(customerId);
    sessionStorage.setItem("isUserAuthenticated", "true");
    sessionStorage.setItem("userRole", role);
    sessionStorage.setItem("customerId", customerId);
  };

  const handleLogout = () => {
    sessionStorage.removeItem("isUserAuthenticated");
    sessionStorage.removeItem("userRole");
    sessionStorage.removeItem("customerId");

    setUserAuthorization(false);
    setUserRole("customer");
    setCustomerId(undefined);
  };

  return (
    <Router>
      <Routes>
        {/* Route pour le formulaire de connexion/inscription */}
        <Route
          path="/"
          element={
            !isUserAuthenticated ? (
              <LoginRegisterForm setUserAuthenticatedStatus={setUserAuthenticatedStatus} />
            ) : (
              <Navigate to={`/${userRole}`} /> // Redirige vers le conteneur approprié selon le rôle
            )
          }
        />

        {/* Conteneur pour les Customers */}
        <Route
          path="/customer"
          element={
            isUserAuthenticated && userRole === "customer" ? (
              <CustomerContainer handleLogout={handleLogout} customerId={customerId} />
            ) : (
              <Navigate to="/" />
            )
          }
        />

        {/* Conteneur pour les Admins */}
        <Route
          path="/admin"
          element={
            isUserAuthenticated && userRole === "admin" ? (
              <AdminCustomerContainer handleLogout={handleLogout} customerId={customerId} />
            ) : (
              <Navigate to="/" />
            )
          }
        />

        {/* Conteneur pour les Sellers */}
        <Route
          path="/seller"
          element={
            isUserAuthenticated && userRole === "seller" ? (
              <SellerContainer handleLogout={handleLogout} />
            ) : (
              <Navigate to="/" />
            )
          }
        />

        {/* Route pour la mise à jour du profil */}
        <Route
          path="/update-profile"
          element={
            isUserAuthenticated ? (
              <ProfileUpdate />
            ) : (
              <Navigate to="/" />
            )
          }
        />
      </Routes>
    </Router>
  );
}

export default App;
